// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: LL table rendered from the shared table model (llTableModel) – captioned data grid with column/row header
//          scopes and a labelled corner, one roving tab stop (arrows/Home/End move between cells), a visible detail
//          line with the hovered/focused cell's rules (was a title tooltip only) and conflicts marked by "!" + a
//          dashed outline (not by colour alone, still visible in forced colours). Used by the viewer and the simulation.

import { useId, useRef, useState, type KeyboardEvent, type Ref } from 'react'
import type { TableCell, TableModel } from '#/lib/tableModel'
import { clampCell, gridMove, type GridCell } from './gridFocus'
import { cellDetail } from '#/lib/tableModel'
import { cx, headCell, tableCell } from './ui'

export interface CellMark {
  /** Replaces the default tone of the cell. */
  className?: string
  /** Visually hidden state text read after the cell content (e.g. "aktuálna bunka"). */
  note?: string
  /** Text shown instead of the (empty) model text. */
  text?: string
  current?: boolean
}

const CORNER = 'Neterminál \\ terminál'

export function LLGrid({
  model,
  caption,
  mark,
  headClass,
  idleCell = null,
  sticky = false,
  boxRef,
  boxClassName,
  className,
}: {
  model: TableModel
  /** Accessible name of the table (visually hidden caption; the panel heading is the visible one). */
  caption: string
  mark?: (row: string, col: string, cell: TableCell) => CellMark | undefined
  headClass?: (symbol: string, axis: 'row' | 'col') => string | undefined
  /** Cell described when nothing is hovered or focused (e.g. the current lookup of the simulation). */
  idleCell?: GridCell | null
  sticky?: boolean
  boxRef?: Ref<HTMLDivElement>
  boxClassName?: string
  className?: string
}) {
  const captionId = useId()
  const detailId = useId()
  const table = useRef<HTMLTableElement>(null)
  const cols = model.header.slice(1)
  const size = { rows: model.rows.length, cols: cols.length }
  const [activeRaw, setActive] = useState<GridCell>(idleCell ?? { row: 0, col: 0 })
  const active = size.rows && size.cols ? clampCell(activeRaw, size) : null
  // Detail line: the last hovered or focused cell; back to the focused / idle cell when the pointer leaves.
  const [shown, setShown] = useState<GridCell | null>(null)
  const focused = useRef<GridCell | null>(null)
  const detailCell = shown ?? idleCell
  const detail = detailCell ? cellDetail(model, detailCell.row, detailCell.col) : ''

  const onKeyDown = (e: KeyboardEvent<HTMLTableCellElement>, at: GridCell) => {
    const next = gridMove(e, at, size)
    // No target (edge of the table): leave the key alone so the box can still scroll natively.
    if (!next) return
    e.preventDefault()
    setActive(next)
    table.current?.querySelector<HTMLElement>(`[data-cell="${next.row}:${next.col}"]`)?.focus()
  }

  return (
    <>
      <div ref={boxRef} role="region" aria-labelledby={captionId} className={cx('overflow-auto', boxClassName)}>
        <table ref={table} role="grid" aria-readonly="true" className={cx('border-collapse font-mono', className)} onMouseLeave={() => setShown(focused.current)}>
          <caption id={captionId} className="sr-only">
            {caption}
          </caption>
          <thead>
            <tr>
              <th scope="col" className={cx(headCell, sticky && 'sticky top-0 left-0 z-20 bg-zinc-900!')}>
                <span className="sr-only">{model.header[0] || CORNER}</span>
              </th>
              {cols.map((c) => (
                <th key={c} scope="col" className={cx(headCell, sticky && 'sticky top-0 z-10 bg-zinc-900!', headClass?.(c, 'col'))}>
                  {c}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {model.rows.map((r, ri) => (
              <tr key={r.head}>
                <th scope="row" className={cx(headCell, 'text-left', sticky && 'sticky left-0 z-10 bg-zinc-900!', headClass?.(r.head, 'row'))}>
                  {r.head}
                </th>
                {r.cells.map((cell, ci) => {
                  const m = mark?.(r.head, cols[ci], cell)
                  const at = { row: ri, col: ci }
                  const isActive = active?.row === ri && active.col === ci
                  return (
                    <td
                      key={cols[ci]}
                      data-cell={`${ri}:${ci}`}
                      data-current={m?.current || undefined}
                      tabIndex={isActive ? 0 : -1}
                      aria-describedby={isActive ? detailId : undefined}
                      onKeyDown={(e) => onKeyDown(e, at)}
                      onFocus={() => {
                        focused.current = at
                        setActive(at)
                        setShown(at)
                      }}
                      onBlur={() => {
                        focused.current = null
                        setShown(null)
                      }}
                      onMouseEnter={() => setShown(at)}
                      className={cx(
                        tableCell,
                        'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-indigo-300',
                        m?.className ?? (cell.conflict ? 'bg-rose-500/20 font-bold text-rose-200' : cell.text ? 'text-indigo-200' : ''),
                        cell.conflict && 'outline-2 -outline-offset-4 outline-rose-300 outline-dashed',
                      )}
                    >
                      {cell.text || m?.text}
                      {cell.conflict && (
                        <>
                          <span aria-hidden="true" className="ml-0.5">
                            !
                          </span>
                          <span className="sr-only">, konflikt</span>
                        </>
                      )}
                      {m?.note && <span className="sr-only">, {m.note}</span>}
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p id={detailId} className="mt-2 min-h-5 font-mono text-xs break-words text-zinc-300">
        {detail || <span className="font-sans text-zinc-400">Bunka pod myšou alebo s fokusom (šípky medzi bunkami) ukáže svoje pravidlá.</span>}
      </p>
    </>
  )
}
